// Offline + install support. The service worker (generated by vite-plugin-pwa / Workbox)
// precaches every file on first visit, so later visits work with no network at all.

import { useSyncExternalStore } from 'react';
import { registerSW } from 'virtual:pwa-register';

interface InstallPromptEvent extends Event {
  prompt(): Promise<void>;
  userChoice: Promise<{ outcome: 'accepted' | 'dismissed' }>;
}

export interface PwaSnapshot {
  /** 'pwa': served over http(s) with a service worker; 'file': the single-file build opened from disk or another viewer. */
  mode: 'pwa' | 'file';
  offlineReady: boolean;
  justBecameReady: boolean;
  needRefresh: boolean;
  canInstall: boolean;
  installed: boolean;
  ios: boolean;
  persisted: boolean | null;
}

const isStandalone = (): boolean => {
  try {
    return window.matchMedia('(display-mode: standalone)').matches || (navigator as unknown as { standalone?: boolean }).standalone === true;
  } catch {
    return false;
  }
};

const swSupported =
  import.meta.env.MODE !== 'single' &&
  typeof navigator !== 'undefined' &&
  'serviceWorker' in navigator &&
  (location.protocol === 'https:' || location.hostname === 'localhost' || location.hostname === '127.0.0.1');

let snap: PwaSnapshot = {
  mode: swSupported ? 'pwa' : 'file',
  offlineReady: swSupported && !!navigator.serviceWorker.controller,
  justBecameReady: false,
  needRefresh: false,
  canInstall: false,
  installed: isStandalone(),
  ios: typeof navigator !== 'undefined' && (/iPad|iPhone|iPod/.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1)),
  persisted: null,
};
const listeners = new Set<() => void>();
const set = (patch: Partial<PwaSnapshot>) => {
  snap = { ...snap, ...patch };
  listeners.forEach((l) => l());
};

let deferredPrompt: InstallPromptEvent | null = null;
let updateSW: (reload?: boolean) => Promise<void> = async () => {};

if (swSupported) {
  updateSW = registerSW({
    onOfflineReady: () => set({ offlineReady: true, justBecameReady: true }),
    onNeedRefresh: () => set({ needRefresh: true }),
  });
  window.addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault();
    deferredPrompt = e as InstallPromptEvent;
    set({ canInstall: true });
  });
  window.addEventListener('appinstalled', () => {
    deferredPrompt = null;
    set({ canInstall: false, installed: true });
  });
}

try {
  void navigator.storage?.persisted?.().then((p) => {
    set({ persisted: p });
    // Installed apps are usually granted persistence without a prompt; ask once.
    if (!p && isStandalone()) void requestPersist();
  });
} catch {
  /* Storage API unavailable */
}

export async function requestPersist(): Promise<boolean> {
  try {
    const ok = (await navigator.storage?.persist?.()) ?? false;
    set({ persisted: ok });
    return ok;
  } catch {
    return false;
  }
}

export async function install(): Promise<void> {
  if (!deferredPrompt) return;
  await deferredPrompt.prompt();
  const choice = await deferredPrompt.userChoice;
  deferredPrompt = null;
  set({ canInstall: false, installed: choice.outcome === 'accepted' || snap.installed });
}

export function applyUpdate() {
  void updateSW(true);
  // The new version normally reloads the page itself; reload anyway if that handoff stalls.
  setTimeout(() => window.location.reload(), 3000);
}
export const dismissReady = () => set({ justBecameReady: false });

export function usePwa(): PwaSnapshot {
  return useSyncExternalStore(
    (l) => {
      listeners.add(l);
      return () => listeners.delete(l);
    },
    () => snap,
  );
}
